import { createHash } from "node:crypto";
import type { AuthProvider } from "#lib/server/auth/types.js";

/** Google OAuth app settings from `.env` */
const config = {
	clientId: process.env.GOOGLE_CLIENT_ID,
	clientSecret: process.env.GOOGLE_CLIENT_SECRET,
	redirectURI: `${process.env.DOMAIN_URL}/api/auth/google/callback`,
	scopes: ["openid", "profile", "email"],
};

/** Google sign in; the `auth-google` item installs this file as `src/lib/server/auth/provider.ts` */
export const authProvider: AuthProvider = {
	name: "google",
	createAuthorizationURL(state: string, codeVerifier: string) {
		// PKCE: Google gets the hashed verifier now and the plain one on the token exchange.
		const codeChallenge = createHash("sha256").update(codeVerifier).digest("base64url");
		const url = new URL("https://accounts.google.com/o/oauth2/v2/auth");
		url.searchParams.set("response_type", "code");
		url.searchParams.set("client_id", config.clientId);
		url.searchParams.set("redirect_uri", config.redirectURI);
		url.searchParams.set("state", state);
		url.searchParams.set("scope", config.scopes.join(" "));
		url.searchParams.set("code_challenge_method", "S256");
		url.searchParams.set("code_challenge", codeChallenge);
		return url;
	},
	async validateAuthorizationCode(code: string, codeVerifier: string) {
		try {
			// Exchange the code and PKCE verifier for tokens
			const tokenReq = await fetch("https://oauth2.googleapis.com/token", {
				method: "POST",
				headers: { Accept: "application/json", "Content-Type": "application/x-www-form-urlencoded" },
				body: new URLSearchParams({
					grant_type: "authorization_code",
					code: code,
					code_verifier: codeVerifier,
					client_id: config.clientId,
					client_secret: config.clientSecret,
					redirect_uri: config.redirectURI,
				}),
			});
			const tokens: GoogleTokensRes = await tokenReq.json();
			// If the exchange failed: return error
			if ("error" in tokens) return { error: true, data: tokens.error_description ?? tokens.error };
			// The ID token came straight from Google over HTTPS, so its payload can be read without checking the signature
			const claims: GoogleClaimsRes = JSON.parse(Buffer.from(tokens.id_token.split(".")[1], "base64url").toString());
			const accessToken = tokens.access_token;
			const scopes = tokens.scope.split(" ").map((data) => data.split("/").pop()!);
			const accessTokenExpiresAt = new Date(Date.now() + tokens.expires_in * 1000);
			// If email is not verified: return error
			if (!claims.email_verified) return { error: true, data: "Your email must be verified to continue." };
			// Return data
			return {
				error: false,
				data: {
					token: { value: accessToken, scopes, expiresAt: accessTokenExpiresAt },
					user: { id: claims.sub, email: claims.email, image: claims.picture },
				},
			};
		} catch (error: any) {
			return { error: true, data: error.message };
		}
	},
};

/** Google token exchange response, which is either the tokens or an error */
export type GoogleTokensRes =
	| {
			/** Access token for Google APIs */
			access_token: string;
			/** Seconds until the access token expires */
			expires_in: number;
			/** Space separated granted scopes */
			scope: string;
			/** JWT with the user claims, present when the `openid` scope is requested */
			id_token: string;
			/** Token type, always `Bearer` */
			token_type: string;
	  }
	| {
			/** Error code, such as `invalid_grant` */
			error: string;
			/** Readable error message */
			error_description?: string;
	  };

export interface GoogleClaimsRes {
	sub: string; // google id
	email: string;
	email_verified: boolean;
	picture: string;
	given_name: string;
	name: string;
}

import { randomUUID } from "node:crypto";
import { eq } from "drizzle-orm";
import { db, schema } from "#lib/server/drizzle/index.js";
import type { AuthDb, AuthProfile, AuthSession } from "#lib/server/auth/types.js";
const { users, sessions } = schema;

/** SQLite version of the auth database calls, built on the Drizzle utility in `src/lib/server/drizzle` */
export const authDb: AuthDb = {
	async createSession(session: AuthSession) {
		await db.insert(sessions).values(session);
	},
	async findSession(id: string) {
		const session = await db.query.sessions.findFirst({ where: { id } });
		// If no session has this id: return nothing.
		return session ?? null;
	},
	async updateSessionExpiry(id: string, expiresAt: Date) {
		await db.update(sessions).set({ expiresAt }).where(eq(sessions.id, id));
	},
	async deleteSession(id: string) {
		await db.delete(sessions).where(eq(sessions.id, id));
	},
	async findUser(id: string) {
		const user = await db.query.users.findFirst({ where: { id }, columns: { id: true, email: true, image: true } });
		// If no user has this id: return nothing.
		return user ?? null;
	},
	async upsertUser(profile: AuthProfile) {
		const now = new Date();
		// Insert a new user, or refresh the avatar when the email already exists.
		const [user] = await db
			.insert(users)
			.values({ id: randomUUID(), email: profile.email, image: profile.image, createdAt: now, updatedAt: now })
			.onConflictDoUpdate({ target: users.email, set: { image: profile.image, updatedAt: now } })
			.returning({ id: users.id, email: users.email, image: users.image });
		// If SQLite returned no row: the insert failed, so stop sign in.
		if (!user) throw new Error(`Could not save the user ${profile.email}.`);
		return user;
	},
};

import { redirect } from "@sveltejs/kit";
import { authProvider } from "#lib/server/auth/provider.js";
import { generateToken, setCookie } from "#lib/server/auth/session.js";
import type { RequestHandler } from "./$types";

/** Redirects to the Google sign in page */
export const GET: RequestHandler = async (event) => {
	const callbackURL = event.url.searchParams.get("callbackURL");
	// If the user is already signed in: go home.
	if (event.locals.userData) redirect(302, "/");

	const state = generateToken();
	const codeVerifier = generateToken();
	const authorizationURL = authProvider.createAuthorizationURL(state, codeVerifier);
	// Save the state and PKCE verifier to check on the callback.
	setCookie(event, "google_oauth_state", state);
	setCookie(event, "google_code_verifier", codeVerifier);
	// If a callbackURL was given: save it to redirect there after the callback.
	if (callbackURL) setCookie(event, "oauth_callback_url", callbackURL);

	return redirect(302, authorizationURL.toString(), { external: true });
};

import { error, redirect } from "@sveltejs/kit";
import { authDb } from "#lib/server/auth/db.js";
import { authProvider } from "#lib/server/auth/provider.js";
import { createAndSetSession } from "#lib/server/auth/session.js";
import type { RequestHandler } from "./$types";

/** Finishes Google sign in, then creates or updates the user and starts a session */
export const GET: RequestHandler = async (event) => {
	const oauthState = event.url.searchParams.get("state");
	const oauthCode = event.url.searchParams.get("code");
	const cookieState = event.cookies.get("google_oauth_state") ?? null;
	const cookieCodeVerifier = event.cookies.get("google_code_verifier") ?? null;
	const callbackURL = event.cookies.get("oauth_callback_url") ?? null;

	// If the code, state, or verifier is missing, or the state does not match the cookie: stop.
	if (!oauthState || !oauthCode || !cookieState || !cookieCodeVerifier || oauthState !== cookieState) {
		throw error(404, "Something went wrong creating account.");
	}

	const validator = await authProvider.validateAuthorizationCode(oauthCode, cookieCodeVerifier);
	// If Google rejected the code: stop.
	if (validator.error) throw error(501, "Something went wrong while authenticating you.");

	const user = await authDb.upsertUser(validator.data.user);
	await createAndSetSession(event, user.id);

	// Clean up the temporary cookies.
	event.cookies.delete("google_oauth_state", { path: "/" });
	event.cookies.delete("google_code_verifier", { path: "/" });
	event.cookies.delete("oauth_callback_url", { path: "/" });

	return redirect(301, callbackURL || "/");
};
